# region imports
from AlgorithmImports import *
import math
# endregion


# ----------------------------------------------------------------------------- 
# Tunable constants
# -----------------------------------------------------------------------------
UNIVERSE = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

SPY_SMA_PERIOD = 50            # "its moving average" -> simple moving average of the close
AAPL_RSI_PERIOD = 14           # "14-day RSI"
RSI_SELL_LEVEL = 60.0          # "RSI closes above 60" (level test, not a cross)
RED_DAYS_REQUIRED = 3          # "red for 3 consecutive days"
STRATEGY_A_ALLOCATION = 0.40   # "invest 40% of total portfolio value"
STRATEGY_B_BUY_CASH = 20000.0  # "buy $20,000 ... if at least $20,000 cash is available"


# -----------------------------------------------------------------------------
# A strategy's private lot: it only ever sells shares it bought itself.
# -----------------------------------------------------------------------------
class StrategyLot:

    def __init__(self, algorithm, symbol, owner):
        self.algorithm = algorithm
        self.symbol = symbol
        self.owner = owner
        self.shares = 0

    @property
    def is_open(self):
        return self.shares > 0

    def buy(self, quantity, reason):
        quantity = int(quantity)
        if quantity <= 0:
            return
        ticket = self.algorithm.market_order(
            self.symbol, quantity, tag=f"{self.owner} BUY | {reason}")
        self.algorithm.register_lot_order(ticket, self, quantity)
        self.shares += quantity

    def sell(self, quantity, reason):
        quantity = int(min(int(quantity), self.shares))
        if quantity <= 0:
            return
        ticket = self.algorithm.market_order(
            self.symbol, -quantity, tag=f"{self.owner} SELL | {reason}")
        self.algorithm.register_lot_order(ticket, self, -quantity)
        self.shares -= quantity

    def liquidate(self, reason):
        """Sell the lot's entire remaining position; the lot is then closed."""
        self.sell(self.shares, reason)


# -----------------------------------------------------------------------------
# Slot 1 - Strategy A (SPY): close vs. its moving average.
# -----------------------------------------------------------------------------
class StrategyA:

    NAME = "Strategy A"

    def __init__(self, algorithm, symbol):
        self.algorithm = algorithm
        self.symbol = symbol
        self.lot = StrategyLot(algorithm, symbol, self.NAME)

    def _values(self, ctx):
        today_close = ctx["bars"]["SPY"].close
        today_sma = self.algorithm.spy_sma.current.value
        yesterday_close = ctx["yesterday_close"]["SPY"]
        yesterday_sma = ctx["yesterday_spy_sma"]
        return today_close, today_sma, yesterday_close, yesterday_sma

    def try_sell(self, ctx):
        # Sell reason is only evaluated while the lot is non-empty.
        if not self.lot.is_open:
            return
        close, sma, y_close, y_sma = self._values(ctx)
        # Crosses below: yesterday close >= yesterday SMA and today close < today SMA.
        if y_close >= y_sma and close < sma:
            self.lot.liquidate("SPY close crossed below its moving average")

    def try_buy(self, ctx):
        # Buy reason is only evaluated while the lot is empty.
        if self.lot.is_open:
            return
        close, sma, y_close, y_sma = self._values(ctx)
        # Crosses above: yesterday close <= yesterday SMA and today close > today SMA.
        if y_close <= y_sma and close > sma:
            target_value = STRATEGY_A_ALLOCATION * self.algorithm.portfolio.total_portfolio_value
            quantity = int(math.floor(target_value / close))
            self.lot.buy(quantity, "SPY close crossed above its moving average")


# -----------------------------------------------------------------------------
# Slot 2 - Strategy B (AAPL): 3 red days in, RSI(14) above 60 out.
# -----------------------------------------------------------------------------
class StrategyB:

    NAME = "Strategy B"

    def __init__(self, algorithm, symbol):
        self.algorithm = algorithm
        self.symbol = symbol
        self.lot = StrategyLot(algorithm, symbol, self.NAME)

    def try_sell(self, ctx):
        if not self.lot.is_open:
            return
        if self.algorithm.aapl_rsi.current.value > RSI_SELL_LEVEL:
            self.lot.liquidate("AAPL 14-day RSI closed above 60")

    def try_buy(self, ctx):
        if self.lot.is_open:
            return
        # Satisfied on any day that completes 3 or more consecutive red days.
        if self.algorithm.red_streak["AAPL"] < RED_DAYS_REQUIRED:
            return
        close = ctx["bars"]["AAPL"].close
        available_cash = self.algorithm.portfolio.cash
        if available_cash < STRATEGY_B_BUY_CASH:
            return  # otherwise do nothing this bar; the reason may fire again later
        quantity = int(math.floor(STRATEGY_B_BUY_CASH / close))
        self.lot.buy(quantity, "AAPL red for 3 consecutive days")


# -----------------------------------------------------------------------------
# Template: 2 slots, no gate, both slots run independently in parallel.
# -----------------------------------------------------------------------------
class ParallelTemplate:

    def __init__(self, slots):
        self.slots = list(slots)

    def on_bar(self, ctx):
        # Sells before buys, in slot order.
        for slot in self.slots:
            slot.try_sell(ctx)
        for slot in self.slots:
            slot.try_buy(ctx)


# -----------------------------------------------------------------------------
# Algorithm
# -----------------------------------------------------------------------------
class ParallelTwoSlotTemplateAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.symbols = {}
        for ticker in UNIVERSE:
            equity = self.add_equity(ticker, Resolution.DAILY)
            self.symbols[ticker] = equity.symbol

        self.set_benchmark(self.symbols["SPY"])

        # --- market state (always computed continuously from data) ---
        self.prev_close = {ticker: None for ticker in UNIVERSE}
        self.red_streak = {ticker: 0 for ticker in UNIVERSE}

        # Indicators are updated manually from the daily bars so that the value
        # used by a rule is unambiguously today's value.
        self.spy_sma = SimpleMovingAverage(SPY_SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(AAPL_RSI_PERIOD, MovingAverageType.WILDERS)
        self.prev_spy_sma = None

        # order id -> [lot, expected signed quantity, filled signed quantity]
        self._pending_orders = {}

        self.strategy_a = StrategyA(self, self.symbols["SPY"])
        self.strategy_b = StrategyB(self, self.symbols["AAPL"])
        self.template = ParallelTemplate([self.strategy_a, self.strategy_b])

    # ------------------------------------------------------------------ data
    def on_data(self, data: Slice):
        if data is None:
            return

        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.bars.contains_key(symbol):
                continue
            bar = data.bars[symbol]
            if bar is None or bar.close <= 0:
                continue
            bars[ticker] = bar

        # Snapshot yesterday's values before folding today's bar into the state.
        yesterday_close = dict(self.prev_close)
        yesterday_spy_sma = self.prev_spy_sma

        self._update_market_state(bars)

        # If today's bar is missing for ANY subscribed ticker, skip all rules.
        if len(bars) != len(UNIVERSE):
            return

        # Do not trade until every indicator / rolling window is fully formed.
        if not self.spy_sma.is_ready or not self.aapl_rsi.is_ready:
            return
        if yesterday_spy_sma is None:
            return
        if any(yesterday_close[ticker] is None for ticker in UNIVERSE):
            return

        ctx = {
            "bars": bars,
            "yesterday_close": yesterday_close,
            "yesterday_spy_sma": yesterday_spy_sma,
        }
        self.template.on_bar(ctx)

    def _update_market_state(self, bars):
        for ticker, bar in bars.items():
            close = bar.close
            previous = self.prev_close[ticker]
            if previous is not None:
                if close < previous:
                    self.red_streak[ticker] += 1   # strictly below -> red day
                else:
                    self.red_streak[ticker] = 0
            self.prev_close[ticker] = close

        if "SPY" in bars:
            spy_bar = bars["SPY"]
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)
            self.prev_spy_sma = self.spy_sma.current.value if self.spy_sma.is_ready else None

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

    # ---------------------------------------------------------- lot bookkeeping
    def register_lot_order(self, ticket, lot, signed_quantity):
        if ticket is None:
            return
        self._pending_orders[ticket.order_id] = [lot, int(signed_quantity), 0]

    def on_order_event(self, order_event: OrderEvent):
        record = self._pending_orders.get(order_event.order_id)
        if record is None:
            return

        lot, expected, filled = record
        filled += int(order_event.fill_quantity)
        record[2] = filled

        status = order_event.status
        if status == OrderStatus.FILLED:
            lot.shares = max(0, lot.shares + (filled - expected))
            del self._pending_orders[order_event.order_id]
        elif status in (OrderStatus.CANCELED, OrderStatus.INVALID):
            lot.shares = max(0, lot.shares + (filled - expected))
            del self._pending_orders[order_event.order_id]

