# region imports
from AlgorithmImports import *
import math
# endregion


class ParallelTwoSlotTemplateAlgorithm(QCAlgorithm):
    """
    One template, two slots, no gate. Both slots run independently, in parallel.

      Slot 1 - Strategy A (SPY)
        buy  : SPY close crosses above its moving average  -> invest 40% of TPV
        sell : SPY close crosses below its moving average  -> liquidate lot A

      Slot 2 - Strategy B (AAPL)
        buy  : AAPL red 3 consecutive days -> buy $20,000 of AAPL if $20,000 cash available
        sell : AAPL 14-day RSI above 60    -> liquidate lot B

    Every rule is evaluated once per daily bar, after the close. Each strategy owns a
    private lot: it only ever sells shares it bought, its buy reason is tested only while
    its lot is empty, its sell reason only while its lot is non-empty, and sells are
    evaluated before buys.
    """

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    SMA_PERIOD = 50                 # "its moving average" for SPY
    RSI_PERIOD = 14
    A_ALLOCATION = 0.40             # 40% of total portfolio value
    B_TRADE_CASH = 20000.0          # $20,000 per Strategy B entry
    B_RED_DAYS = 3                  # red for 3 consecutive days
    B_RSI_EXIT = 60.0               # RSI closes above 60

    CLOSED_STATUSES = (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID)

    # ------------------------------------------------------------------ setup
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.symbols = {}
        for ticker in self.TICKERS:
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Indicators are driven manually from the daily bars so every rule sees exactly
        # the values described by the semantics contract, on the bar it is evaluated.
        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(self.RSI_PERIOD, MovingAverageType.WILDERS)

        # Market state. Always advanced from data, never paused by any rule skip.
        self.prev_spy_close = None
        self.prev_spy_sma = None
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        # Private lots, one per slot.
        self.lot_a = {"name": "A", "symbol": self.spy, "shares": 0, "pending": 0}
        self.lot_b = {"name": "B", "symbol": self.aapl, "shares": 0, "pending": 0}

        # order id -> {lot, quantity, applied}; keeps lot bookkeeping exact across fills.
        self.order_lots = {}

        # Cash committed by orders submitted on the current bar (they fill next open).
        self._cash_committed_today = 0.0

    # --------------------------------------------------------------- main loop
    def on_data(self, slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            bar = slice.bars[symbol] if slice.bars.contains_key(symbol) else None
            if bar is not None and bar.close > 0:
                bars[ticker] = bar

        # ---- 1. market state: computed continuously, independent of any rule ----
        spy_close = None
        spy_sma = None
        if "SPY" in bars:
            spy_close = float(bars["SPY"].close)
            self.spy_sma.update(IndicatorDataPoint(self.spy, self.time, spy_close))
            if self.spy_sma.is_ready:
                spy_sma = float(self.spy_sma.current.value)

        aapl_close = None
        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].close)
            self.aapl_rsi.update(IndicatorDataPoint(self.aapl, self.time, aapl_close))
            if self.prev_aapl_close is not None:
                if aapl_close < self.prev_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        try:
            # ---- 2. rule evaluation ----
            # Today's bar missing for at least one subscribed ticker: skip ALL rules.
            if len(bars) < len(self.TICKERS):
                return

            self._cash_committed_today = 0.0

            # Sells before buys, for every slot.
            self._strategy_a_sell(spy_close, spy_sma)
            self._strategy_b_sell()
            self._strategy_a_buy(spy_close, spy_sma)
            self._strategy_b_buy(aapl_close)
        finally:
            # ---- 3. roll market state forward, whether or not rules ran ----
            if spy_close is not None:
                self.prev_spy_close = spy_close
                self.prev_spy_sma = spy_sma
            if aapl_close is not None:
                self.prev_aapl_close = aapl_close

    # ------------------------------------------------------- slot 1: strategy A
    def _strategy_a_sell(self, close, sma):
        lot = self.lot_a
        if not self._lot_open(lot):
            return
        if not self._ready_a(sma):
            return
        # crosses below: yesterday close >= yesterday SMA, today close < today SMA
        if self.prev_spy_close >= self.prev_spy_sma and close < sma:
            self._submit(lot, -lot["shares"], close, "A sell: SPY crossed below SMA")

    def _strategy_a_buy(self, close, sma):
        lot = self.lot_a
        if not self._lot_empty(lot):
            return
        if not self._ready_a(sma):
            return
        # crosses above: yesterday close <= yesterday SMA, today close > today SMA
        if not (self.prev_spy_close <= self.prev_spy_sma and close > sma):
            return
        target = self.A_ALLOCATION * float(self.portfolio.total_portfolio_value)
        quantity = int(math.floor(target / close))
        if quantity > 0:
            self._submit(lot, quantity, close, "A buy: SPY crossed above SMA")

    def _ready_a(self, sma):
        return (sma is not None
                and self.prev_spy_sma is not None
                and self.prev_spy_close is not None)

    # ------------------------------------------------------- slot 2: strategy B
    def _strategy_b_sell(self):
        lot = self.lot_b
        if not self._lot_open(lot):
            return
        if not self.aapl_rsi.is_ready:
            return
        if float(self.aapl_rsi.current.value) > self.B_RSI_EXIT:
            price = float(self.securities[self.aapl].close)
            self._submit(lot, -lot["shares"], price, "B sell: AAPL RSI(14) above 60")

    def _strategy_b_buy(self, close):
        lot = self.lot_b
        if not self._lot_empty(lot):
            return
        # RSI(14) drives this strategy's exit, so it must be formed before it may trade.
        if not self.aapl_rsi.is_ready:
            return
        if self.aapl_red_streak < self.B_RED_DAYS:
            return
        # "buy $20,000 if available": not enough cash -> do nothing at all this bar.
        if self._available_cash() < self.B_TRADE_CASH:
            return
        quantity = int(math.floor(self.B_TRADE_CASH / close))
        if quantity > 0:
