        quantity = int(min(int(quantity), self.shares))
        if quantity <= 0:
            return False
        ticket = self.algorithm.market_order(self.symbol, -quantity, tag=f"{self.name} SELL: {reason}")
        if ticket is None or ticket.status == OrderStatus.INVALID:
            return False
        self.shares -= quantity
        return True

    def liquidate(self, reason):
        return self.sell(self.shares, reason)


