      Slot 1 - Strategy A (SPY): buy on close crossing above the 100-day SMA
               (40% of total portfolio value), sell on close crossing below.
      Slot 2 - Strategy B (AAPL): buy $20,000 after 3 consecutive red days
               (only if $20,000 cash is available), sell when 14-day RSI > 60.
    """

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    # region initialization
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.symbols = {}
        for ticker in self.TICKERS:
            equity = self.add_equity(ticker, Resolution.DAILY)
            self.symbols[ticker] = equity.symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # --- market state, computed continuously from data ---
        self.prev_close = {symbol: None for symbol in self.symbols.values()}
        self.red_streak = {symbol: 0 for symbol in self.symbols.values()}
        self.green_streak = {symbol: 0 for symbol in self.symbols.values()}

        # SPY close vs 100-day SMA, today's and yesterday's readings
        self.spy_sma = SimpleMovingAverage(100)
        self.spy_close_today = None
        self.spy_sma_today = None
        self.spy_close_yesterday = None
        self.spy_sma_yesterday = None

        # AAPL 14-day Wilder's RSI
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)
        self.aapl_rsi_today = None

        # --- slots ---
        self.lot_a = StrategyLot(self, "Strategy A", self.spy)
        self.lot_b = StrategyLot(self, "Strategy B", self.aapl)

        # order id -> (lot, signed quantity) so rejected orders can be unwound
        self._lot_orders = {}

        self.set_warm_up(150, Resolution.DAILY)
    # endregion

    # region order bookkeeping
    def register_lot_order(self, ticket, lot, signed_quantity):
        if ticket is not None:
            self._lot_orders[ticket.order_id] = (lot, signed_quantity)

    def on_order_event(self, order_event):
        record = self._lot_orders.get(order_event.order_id)
        if record is None:
            return

        lot, signed_quantity = record

        if order_event.status in (OrderStatus.INVALID, OrderStatus.CANCELED):
            # the order never went through - undo the optimistic lot update
            lot.shares -= signed_quantity
            if lot.shares < 0:
                lot.shares = 0
            self._lot_orders.pop(order_event.order_id, None)
        elif order_event.status == OrderStatus.FILLED:
            self._lot_orders.pop(order_event.order_id, None)
    # endregion

    # region data handling
    def on_data(self, data):
        bars = {}
        for symbol in self.symbols.values():
            if data.bars.contains_key(symbol):
                bar = data.bars[symbol]
                if bar is not None and bar.close > 0:
                    bars[symbol] = bar

        # market-state quantities are always updated from whatever data arrived
        self._update_market_state(bars)

        if self.is_warming_up:
            return

        # skip ALL rule evaluation when any subscribed ticker is missing today
        if len(bars) != len(self.symbols):
            return

        # nothing trades until every indicator / rolling window is fully formed
        if not self._is_ready():
            return

        # sells before buys, slot order within each pass
        self._strategy_a_sell()
        self._strategy_b_sell()
        self._strategy_a_buy(bars[self.spy])
        self._strategy_b_buy(bars[self.aapl])

    def _update_market_state(self, bars):
        for symbol, bar in bars.items():
            close = bar.close
            previous = self.prev_close[symbol]

            if previous is not None:
                if close < previous:
                    self.red_streak[symbol] += 1
                    self.green_streak[symbol] = 0
                elif close > previous:
                    self.green_streak[symbol] += 1
                    self.red_streak[symbol] = 0
                else:
                    self.red_streak[symbol] = 0
                    self.green_streak[symbol] = 0

            self.prev_close[symbol] = close

            if symbol == self.spy:
                self.spy_close_yesterday = self.spy_close_today
                self.spy_sma_yesterday = self.spy_sma_today
                self.spy_sma.update(bar.end_time, close)
                self.spy_close_today = close
                self.spy_sma_today = (
                    self.spy_sma.current.value if self.spy_sma.is_ready else None
                )

            if symbol == self.aapl:
                self.aapl_rsi.update(bar.end_time, close)
                self.aapl_rsi_today = (
                    self.aapl_rsi.current.value if self.aapl_rsi.is_ready else None
                )

    def _is_ready(self):
        if not self.spy_sma.is_ready or not self.aapl_rsi.is_ready:
            return False
        if self.spy_close_today is None or self.spy_sma_today is None:
            return False
        if self.spy_close_yesterday is None or self.spy_sma_yesterday is None:
            return False
        if self.aapl_rsi_today is None:
            return False
        return True
    # endregion

    # region cross helpers
    def _spy_crossed_above_sma(self):
        return (self.spy_close_yesterday <= self.spy_sma_yesterday
                and self.spy_close_today > self.spy_sma_today)

    def _spy_crossed_below_sma(self):
        return (self.spy_close_yesterday >= self.spy_sma_yesterday
                and self.spy_close_today < self.spy_sma_today)
    # endregion

    # region slot 1 - Strategy A (SPY)
    def _strategy_a_sell(self):
        if not self.lot_a.is_open:
            return
        if self._spy_crossed_below_sma():
            self.lot_a.liquidate()

    def _strategy_a_buy(self, spy_bar):
        if self.lot_a.is_open:
            return
        if not self._spy_crossed_above_sma():
            return

        target_value = 0.40 * self.portfolio.total_portfolio_value
        quantity = math.floor(target_value / spy_bar.close)
        if quantity > 0:
            self.lot_a.buy(quantity)
    # endregion

    # region slot 2 - Strategy B (AAPL)
    def _strategy_b_sell(self):
        if not self.lot_b.is_open:
            return
        if self.aapl_rsi_today > 60:
            self.lot_b.liquidate()

    def _strategy_b_buy(self, aapl_bar):
        if self.lot_b.is_open:
            return
        if self.red_streak[self.aapl] < 3:
            return

        budget = 20000.0
        if self.portfolio.cash < budget:
            # not enough cash: do nothing this bar, the reason may fire again later
            return

        quantity = math.floor(budget / aapl_bar.close)
        if quantity > 0:
            self.lot_b.buy(quantity)
    # endregion
