class _StrategyLot:
    """Private share lot owned by a single strategy slot.

    Each strategy sells only the shares it bought, so holdings are tracked here
    rather than read off the shared portfolio.
    """

    def __init__(self, name, symbol):
        self.name = name
        self.symbol = symbol
        self.shares = 0          # filled shares currently owned by this strategy
        self.pending_qty = 0     # signed quantity of this strategy's unfilled orders
        self.pending_cash = 0.0  # cash earmarked by this strategy's unfilled buys

    @property
    def is_empty(self):
        return self.shares == 0 and self.pending_qty == 0

    @property
    def is_open(self):
        return self.shares > 0 and self.pending_qty == 0


class TwoSlotParallelTemplateAlgorithm(QCAlgorithm):
    """One template, two slots, no gate. Both slots run independently in parallel.

    Slot 1 - Strategy A (SPY): buy when close crosses above the 100-day SMA
             (invest 40% of total portfolio value); sell when close crosses
             below the 100-day SMA (liquidate the lot).
    Slot 2 - Strategy B (AAPL): buy $20,000 after 3 consecutive red days if at
             least $20,000 cash is available; sell when the 14-day RSI closes
             above 60 (liquidate the lot).
    """

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    SMA_PERIOD = 100
    RSI_PERIOD = 14
    RSI_SELL_LEVEL = 60.0
    RED_DAYS_REQUIRED = 3
    STRATEGY_A_ALLOCATION = 0.40
    STRATEGY_B_CASH = 20000.0

    # ------------------------------------------------------------------ setup
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in self.TICKERS:
            equity = self.AddEquity(ticker, Resolution.Daily)
            equity.SetDataNormalizationMode(DataNormalizationMode.Adjusted)
            self.symbols[ticker] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Indicators are updated manually so that market state is always derived
        # from data in a well-defined order relative to rule evaluation.
        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(self.RSI_PERIOD, MovingAverageType.Wilders)

        # Continuously maintained market state
        self.prev_close = {t: None for t in self.TICKERS}
        self.red_streak = {t: 0 for t in self.TICKERS}
        self.prev_spy_sma = None

        # Private lots, one per slot
        self.lots = {
            "A": _StrategyLot("Strategy A", self.spy),
            "B": _StrategyLot("Strategy B", self.aapl),
        }

        # orderId -> {"key", "remaining", "price"} for outstanding orders
        self.open_orders = {}

        # Enough history for the 100-day SMA, the 14-day RSI and the previous
        # day's values used by the cross / red-streak rules.
        self.SetWarmUp(self.SMA_PERIOD + 60, Resolution.Daily)

    # ------------------------------------------------------------- main loop
    def OnData(self, data):
        # --- collect today's bars ------------------------------------------
        bars = {}
        for ticker in self.TICKERS:
            symbol = self.symbols[ticker]
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]
                if bar is not None:
                    bars[ticker] = bar

        # --- snapshot yesterday's values before they are overwritten --------
        prev_spy_close = self.prev_close["SPY"]
        prev_spy_sma = self.prev_spy_sma

        # --- update market state (always, regardless of rule evaluation) ----
        for ticker, bar in bars.items():
            previous = self.prev_close[ticker]
            if previous is not None:
                if bar.Close < previous:
                    self.red_streak[ticker] += 1
                else:
                    self.red_streak[ticker] = 0

        if "SPY" in bars:
            self.spy_sma.Update(bars["SPY"].EndTime, bars["SPY"].Close)
        if "AAPL" in bars:
            self.aapl_rsi.Update(bars["AAPL"].EndTime, bars["AAPL"].Close)

        try:
            self._evaluate_rules(bars, prev_spy_close, prev_spy_sma)
        finally:
            # --- roll state forward ----------------------------------------
            for ticker, bar in bars.items():
                self.prev_close[ticker] = bar.Close
            if "SPY" in bars and self.spy_sma.IsReady:
                self.prev_spy_sma = self.spy_sma.Current.Value

    def _evaluate_rules(self, bars, prev_spy_close, prev_spy_sma):
        if self.IsWarmingUp:
            return

        # Skip every rule for the day if any subscribed ticker is missing a bar.
        if len(bars) != len(self.TICKERS):
            return

        # Do not trade until every indicator / rolling window is fully formed.
        if not (self.spy_sma.IsReady and self.aapl_rsi.IsReady):
            return
        if prev_spy_close is None or prev_spy_sma is None:
            return

        spy_close = bars["SPY"].Close
        aapl_close = bars["AAPL"].Close
        spy_sma = self.spy_sma.Current.Value
        aapl_rsi = self.aapl_rsi.Current.Value

        if spy_close <= 0 or aapl_close <= 0:
            return

        # Cross definitions: yesterday on one side (inclusive), today strictly
        # on the other. A level being above/below is not a cross.
        crosses_above = (prev_spy_close <= prev_spy_sma) and (spy_close > spy_sma)
        crosses_below = (prev_spy_close >= prev_spy_sma) and (spy_close < spy_sma)

        lot_a = self.lots["A"]
        lot_b = self.lots["B"]

        # ---------------------------- SELLS (evaluated before buys) ---------
        # Slot 1 - Strategy A: SPY closes below its 100-day SMA (cross).
        if lot_a.is_open and crosses_below:
            self._submit("A", self.spy, -lot_a.shares, spy_close)

        # Slot 2 - Strategy B: AAPL 14-day RSI closes above 60 (level).
        if lot_b.is_open and aapl_rsi > self.RSI_SELL_LEVEL:
            self._submit("B", self.aapl, -lot_b.shares, aapl_close)

        # ---------------------------- BUYS ----------------------------------
        # Slot 1 - Strategy A: invest 40% of total portfolio value in SPY.
        if lot_a.is_empty and crosses_above:
            target_value = self.STRATEGY_A_ALLOCATION * self.Portfolio.TotalPortfolioValue
            quantity = int(math.floor(target_value / spy_close))
            if quantity > 0:
                self._submit("A", self.spy, quantity, spy_close)

        # Slot 2 - Strategy B: $20,000 of AAPL after 3 consecutive red days.
        if lot_b.is_empty and self.red_streak["AAPL"] >= self.RED_DAYS_REQUIRED:
            if self._available_cash() >= self.STRATEGY_B_CASH:
                quantity = int(math.floor(self.STRATEGY_B_CASH / aapl_close))
                if quantity > 0:
                    self._submit("B", self.aapl, quantity, aapl_close)
            # otherwise do nothing this bar; the reason may fire again later

    # ------------------------------------------------------- order plumbing
    def _available_cash(self):
        reserved = sum(lot.pending_cash for lot in self.lots.values())
        return self.Portfolio.Cash - reserved

    def _submit(self, key, symbol, quantity, reference_price):
        quantity = int(quantity)
        if quantity == 0:
            return

        ticket = self.MarketOrder(symbol, quantity)
        if ticket is None:
            return
        if ticket.Status in (OrderStatus.Invalid, OrderStatus.Canceled):
            return

        lot = self.lots[key]
        lot.pending_qty += quantity
        if quantity > 0:
            lot.pending_cash += quantity * reference_price

        self.open_orders[ticket.OrderId] = {
            "key": key,
            "remaining": quantity,
            "price": reference_price,
        }

    def OnOrderEvent(self, orderEvent):
        record = self.open_orders.get(orderEvent.OrderId, None)
        if record is None:
            return

        lot = self.lots[record["key"]]
        fill = orderEvent.FillQuantity

        if fill != 0:
            lot.shares += fill
            record["remaining"] -= fill
            lot.pending_qty -= fill
            if fill > 0:
                lot.pending_cash = max(0.0, lot.pending_cash - fill * record["price"])

        if orderEvent.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            remaining = record["remaining"]
            if remaining != 0:
                lot.pending_qty -= remaining
                if remaining > 0:
                    lot.pending_cash = max(0.0, lot.pending_cash - remaining * record["price"])
            del self.open_orders[orderEvent.OrderId]

        if lot.shares < 0:
            lot.shares = 0
        if lot.shares == 0 and lot.pending_qty == 0:
            lot.pending_cash = 0.0

